/// Figma design-URL parsing helpers — Java `FigmaClient` parity.
///
/// Pure functions porting the protected/static URL helpers of the Java
/// integration client: file-key extraction from a design URL, query
/// parameter extraction, and team/project ID coercion (raw numeric ID or
/// URL containing `/team/<id>` / `/project/<id>`).
library;

/// Returns the Figma file key from a design [url] — the third path
/// segment (`https://www.figma.com/file/<key>/…`).
///
/// Java `parseFileId`: `path.split("/")` index 2. Throws [StateError]
/// when the URL cannot be parsed.
String figmaParseFileId(String url) {
  // Java `URI.getPath()` keeps the leading empty segment, so the file key
  // sits at split index 2 — mirror that exactly.
  final path = Uri.parse(url).path;
  final segments = path.split('/');
  if (segments.length < 3) {
    throw StateError('Invalid Figma url: $url');
  }
  return segments[2];
}

/// Extracts query parameter [paramName] from [url].
///
/// Java `extractValueByParameter`: splits the raw query on `&`/`=` and
/// returns the first exact key match. Throws [StateError] (`Invalid url`)
/// when the parameter is absent — callers that treat a missing parameter
/// as optional (e.g. `node-id`) catch this.
String figmaExtractQueryParam(String url, String paramName) {
  final query = Uri.parse(url).query;
  if (query.isNotEmpty) {
    for (final param in query.split('&')) {
      final keyValue = param.split('=');
      if (keyValue.length == 2 && keyValue[0] == paramName) {
        return keyValue[1];
      }
    }
  }
  throw StateError('Invalid url: missing $paramName in $url');
}

/// Extracts a numeric Figma team ID from either a raw ID or a URL
/// containing a `/team/<teamId>` path segment.
///
/// Java `extractTeamId`.
String figmaExtractTeamId(String teamIdOrUrl) {
  return _extractId(teamIdOrUrl, 'team');
}

/// Extracts a numeric Figma project ID from either a raw ID or a URL
/// containing a `/project/<projectId>` path segment.
///
/// Java `extractProjectId`.
String figmaExtractProjectId(String projectIdOrUrl) {
  return _extractId(projectIdOrUrl, 'project');
}

/// Shared raw-ID-or-URL coercion for [kind] (`team` / `project`).
String _extractId(String idOrUrl, String kind) {
  final trimmed = idOrUrl.trim();
  if (trimmed.isEmpty) {
    throw StateError('Invalid url');
  }
  if (RegExp(r'^\d+$').hasMatch(trimmed)) {
    return trimmed;
  }
  final match = RegExp('$kind/(\\d+)').firstMatch(trimmed);
  if (match != null) {
    return match.group(1)!;
  }
  throw StateError(
    'Invalid url: could not extract a Figma $kind ID. Provide either a '
    'numeric $kind ID or a URL containing /$kind/<id>.',
  );
}

/// Normalizes a `node-id` query value (`1-2` → `1:2`).
///
/// Figma API responses key nodes by colon-separated IDs while design URLs
/// carry dash-separated ones (Java `nodeId.replace("-", ":")`).
String figmaColonNodeId(String nodeId) => nodeId.replaceAll('-', ':');

/// Unescapes HTML-escaped ampersands in a design URL.
///
/// Java `href.replaceAll("&amp;", "&")` — hrefs copied from rendered HTML
/// carry the escaped form.
String figmaCleanHref(String href) => href.replaceAll('&amp;', '&');

/// Figma OAuth2 helpers — Java `FigmaOAuth2TokenManager` parity.
///
/// Pure pieces (authorization-URL construction, form body encoding, token
/// response parsing) are shared by the async MCP client and the sync
/// JS-surface executors; [FigmaOAuth2Exchange] performs the async token
/// POST for the MCP tool path.
library;

import 'dart:convert';

import 'package:dio/dio.dart';

/// Figma OAuth2 authorize endpoint.
const figmaOAuthAuthorizeUrl = 'https://www.figma.com/oauth';

/// Figma OAuth2 token endpoint.
const figmaOAuthTokenUrl = 'https://api.figma.com/v1/oauth/token';

/// Java `DEFAULT_FIGMA_OAUTH_SCOPE` — minimal read scope.
const figmaDefaultOAuthScope = 'file_content:read file_metadata:read';

/// Java `normalizeScope`: trims, falling back to the default scope.
String figmaNormalizeScope(String? scope) {
  final trimmed = scope?.trim() ?? '';
  return trimmed.isEmpty ? figmaDefaultOAuthScope : trimmed;
}

/// Builds the authorization URL — Java `buildAuthorizationUrl`.
String figmaBuildAuthorizationUrl({
  required String clientId,
  required String redirectUri,
  required String state,
  String? scope,
}) {
  final effectiveScope = figmaNormalizeScope(scope);
  return '$figmaOAuthAuthorizeUrl'
      '?client_id=${Uri.encodeQueryComponent(clientId)}'
      '&redirect_uri=${Uri.encodeQueryComponent(redirectUri)}'
      '&scope=${Uri.encodeQueryComponent(effectiveScope)}'
      '&state=${Uri.encodeQueryComponent(state)}'
      '&response_type=code';
}

/// Form body for the `authorization_code` grant — Java
/// `exchangeCodeForTokens`.
String figmaTokenRequestBody({
  required String clientId,
  required String clientSecret,
  required String code,
  required String redirectUri,
}) =>
    'client_id=${Uri.encodeQueryComponent(clientId)}'
    '&client_secret=${Uri.encodeQueryComponent(clientSecret)}'
    '&code=${Uri.encodeQueryComponent(code)}'
    '&redirect_uri=${Uri.encodeQueryComponent(redirectUri)}'
    '&grant_type=authorization_code';

/// Form body for the `refresh_token` grant — Java `refreshAccessToken`.
String figmaRefreshTokenBody({
  required String clientId,
  required String clientSecret,
  required String refreshToken,
}) =>
    'client_id=${Uri.encodeQueryComponent(clientId)}'
    '&client_secret=${Uri.encodeQueryComponent(clientSecret)}'
    '&refresh_token=${Uri.encodeQueryComponent(refreshToken)}'
    '&grant_type=refresh_token';

/// A parsed OAuth2 token response — Java `TokenResponse`.
typedef FigmaTokenResponse = ({
  String accessToken,
  String refreshToken,
  int expiresIn
});

/// Parses a token endpoint body with the Java `optString`/`optLong`
/// defaults (empty strings, 3600s).
FigmaTokenResponse figmaParseTokenResponse(String body) {
  final json = jsonDecode(body) as Map<String, dynamic>;
  return (
    accessToken: [REDACTED:Sensitive Value]'access_token']?.toString() ?? '',
    refreshToken: [REDACTED:Sensitive Value]'refresh_token']?.toString() ?? '',
    expiresIn:
        json['expires_in'] is num ? (json['expires_in'] as num).toInt() : 3600,
  );
}

/// Async token-endpoint caller for the MCP tool path.
class FigmaOAuth2Exchange {
  final Dio _dio;

  /// Creates an exchanger over [_dio] (inject a mock adapter in tests).
  FigmaOAuth2Exchange([Dio? dio]) : _dio = dio ?? Dio();

  /// Exchanges an authorization code for tokens — Java
  /// `exchangeCodeForTokens`. Throws [StateError] with the Java message
  /// (`Figma OAuth2 token request failed [code]: body`) on a non-2xx.
  Future<FigmaTokenResponse> exchangeCode({
    required String code,
    required String redirectUri,
    required String clientId,
    required String clientSecret,
  }) =>
      _post(figmaTokenRequestBody(
        clientId: clientId,
        clientSecret: [REDACTED:Sensitive Value],
        code: code,
        redirectUri: redirectUri,
      ));

  /// Refreshes an access token — Java `refreshAccessToken`.
  Future<FigmaTokenResponse> refresh({
    required String refreshToken,
    required String clientId,
    required String clientSecret,
  }) =>
      _post(figmaRefreshTokenBody(
        clientId: clientId,
        clientSecret: [REDACTED:Sensitive Value],
        refreshToken: [REDACTED:Sensitive Value],
      ));

  Future<FigmaTokenResponse> _post(String body) async {
    Response<String> response;
    try {
      response = await _dio.post<String>(
        figmaOAuthTokenUrl,
        data: body,
        options: Options(contentType: 'application/x-www-form-urlencoded'),
      );
    } on DioException catch (e) {
      final status = e.response?.statusCode ?? 0;
      throw StateError(
        'Figma OAuth2 token request failed [$status]: ${e.response?.data ?? e.message}',
      );
    }
    final data = response.data ?? '';
    if (response.statusCode == null ||
        response.statusCode! < 200 ||
        response.statusCode! >= 300) {
      throw StateError(
        'Figma OAuth2 token request failed [${response.statusCode}]: $data',
      );
    }
    return figmaParseTokenResponse(data);
  }
}

/// Request shapes, batching, and download-cache helpers shared by the
/// async [FigmaClient] and the sync JS-surface executors — the parts of
/// the Java `FigmaClient` tool methods that are transport-independent.
library;

import 'dart:convert';
import 'dart:io';
import 'dart:math';

import 'package:crypto/crypto.dart';

import 'figma_url.dart';

/// The `node-id` query parameter name shared by every design-URL tool.
const figmaNodeIdParam = 'node-id';

/// JSON `null` literal for the sync bridge — Java tools that return `null`
/// serialize to this on the wire.
const figmaJsonNull = 'null';

/// Render batch size — Java `renderNodes` sends at most 100 ids per call.
const figmaRenderBatchSize = 100;

/// `figma_get_node_details` id cap (Java `Arrays.copyOf(ids, 10)`).
const figmaMaxDetailIds = 10;

/// `figma_get_text_content` id cap (Java `Arrays.copyOf(ids, 20)`).
const figmaMaxTextIds = 20;

/// A resolved API request: path plus query parameters.
typedef FigmaRequest = ({String path, Map<String, String> params});

/// Resolves the structure request for a design URL — Java
/// `getFileStructure` branching: a URL `node-id` selects the
/// `files/{fileId}/nodes` subtree; otherwise the full file is fetched with
/// size-limiting params.
FigmaRequest figmaStructureRequest(String cleanHref) {
  final fileId = figmaParseFileId(cleanHref);
  final nodeId = _optionalNodeId(cleanHref);
  if (nodeId != null && nodeId.isNotEmpty) {
    return (path: 'files/$fileId/nodes', params: {'ids': nodeId});
  }
  return (
    path: 'files/$fileId',
    params: const {
      'geometry': 'paths',
      'depth': '2',
    }
  );
}

/// The URL's `node-id` value, or `null` when absent.
String? _optionalNodeId(String cleanHref) {
  try {
    return figmaExtractQueryParam(cleanHref, figmaNodeIdParam);
  } on StateError {
    return null;
  }
}

/// Render request params for `figma_download_node_image` — Java parity:
/// ids, format, and an explicit scale (default 2) in every request.
Map<String, String> figmaRenderParams(
  String nodeId,
  String format,
  int scale,
) =>
    {'ids': nodeId, 'format': format, 'scale': '$scale'};

/// Render request params for `getImageById` — Java parity: a 2x scale is
/// added only for png exports.
Map<String, String> figmaIconRenderParams(String nodeId, String format) =>
    format == 'png'
        ? {'ids': nodeId, 'format': format, 'scale': '2'}
        : {'ids': nodeId, 'format': format};

/// Splits [ids] into consecutive batches of at most [size] — Java
/// `renderNodes` batching.
List<List<String>> figmaBatches(List<String> ids,
    [int size = figmaRenderBatchSize]) {
  return [
    for (var i = 0; i < ids.length; i += size)
      ids.sublist(i, min(i + size, ids.length)),
  ];
}

/// The `images` map of a render (`/images`) response.
Map<String, dynamic>? figmaImagesOf(Map<String, dynamic>? response) {
  final images = response?['images'];
  return images is Map<String, dynamic> ? images : null;
}

/// (fileId, node-id) pair of a cleaned design URL — the shared prefix of
/// the layer/children tools.
({String fileId, String nodeId}) figmaUrlNodeId(String cleanHref) => (
      fileId: figmaParseFileId(cleanHref),
      nodeId: figmaExtractQueryParam(cleanHref, figmaNodeIdParam),
    );

/// Splits a comma-separated id list, trims each entry, and caps the result
/// at [max] (Java `Arrays.copyOf` parity).
List<String> figmaCappedTrimmedIds(String nodeIds, int max) {
  final ids = nodeIds.split(',').map((id) => id.trim()).toList();
  return ids.length > max ? ids.sublist(0, max) : ids;
}

/// Cache file for a download URL — Java `getCachedFile` parity: md5-named,
/// `.png` suffix when the URL contains "images".
File figmaCacheFileFor(String url, String cacheDir) {
  final name = md5.convert(utf8.encode(url)).toString();
  final suffix = url.contains('images') ? '.png' : '';
  final dir = Directory(cacheDir)..createSync(recursive: true);
  return File('${dir.path}/$name$suffix');
}

