61:  /// so the dispatcher can serve as a single routing entry point.
83:  late final List<MapEntry<String, _PrefixDispatch>> _routes = [
84:    MapEntry('jira_', JiraSyncTools().dispatch),
85:    MapEntry('github_', _viaHandlers('GitHub', _githubHandlers)),
86:    MapEntry('gitlab_', _viaHandlers('GitLab', _gitlabHandlers)),
87:    MapEntry('confluence_', _confluence.dispatch),
88:    MapEntry('ado_', _viaHandlers('ADO', _adoHandlers)),
