  Future<String?> downloadIconFile(
    String href,
    String nodeId,
    String format,
  ) async {
    try {
      final imageUrl = await getImageById(href, nodeId, format);
      if (imageUrl == null || imageUrl.isEmpty) {
        return null;
      }
      return await downloadImage(imageUrl);
