  /// returns null).
  Future<Map<String, dynamic>?> getFileStructure(String href) async {
    try {
      final request = figmaStructureRequest(figmaCleanHref(href));
      return await _getJson(request.path, queryParams: request.params);
    } on Object {
      return null;
    }
