    if (token == null || token.isEmpty) return null;
    final basePath = _reader.getFigmaBasePath() ?? figmaDefaultBasePath;
    return (
      baseUrl: basePath,
      headers: {
        'Authorization': 'Bearer $token',
        'Content-Type': syncJsonContentType,
