  String _me(Map<String, dynamic> args) {
    return syncWithConfig(_config(), _notConfigured, (config) {
      final resp =
          SyncHttpClient.get('${config.baseUrl}/me', headers: config.headers);
      if (resp.statusCode == 0) {
        return jsonEncode(figmaMeResult(
          error: resp.body,
