    final decoded = _decodeArgs(result);
    final isErrorEnvelope =
        decoded is Map && decoded.length == 1 && decoded['error'] != null;
    if (isErrorEnvelope) {
      return _jsError('Tool execution failed: ${decoded['error']}');
    }
    return result;
